<?php
/**
 * Vite manifest and dev-server resolver.
 *
 * @package DarkMatter_Package
 */

namespace DarkMatter_Theme\Helpers;

/**
 * Resolves development and production assets generated by Vite.
 */
class Vite_Assets {

	/**
	 * Theme filesystem root.
	 *
	 * @var string
	 */
	private $theme_path;

	/**
	 * Theme public URL.
	 *
	 * @var string
	 */
	private $theme_url;

	/**
	 * Vite manifest filesystem path.
	 *
	 * @var string
	 */
	private $manifest_path;

	/**
	 * Vite development marker filesystem path.
	 *
	 * @var string
	 */
	private $hot_file;

	/**
	 * Decoded manifest cached for this resolver instance.
	 *
	 * @var array|null
	 */
	private $manifest;

	/**
	 * Whether the manifest has been loaded for this resolver instance.
	 *
	 * @var bool
	 */
	private $manifest_loaded = false;

	/**
	 * Create the Vite asset resolver.
	 *
	 * @param string $theme_path   Theme filesystem root.
	 * @param string $theme_url    Theme public URL.
	 * @param string $manifest_path Vite manifest filesystem path.
	 * @param string $hot_file     Vite development marker path.
	 */
	public function __construct( string $theme_path, string $theme_url, string $manifest_path, string $hot_file ) {
		$this->theme_path    = rtrim( $theme_path, '/\\' ) . DIRECTORY_SEPARATOR;
		$this->theme_url     = rtrim( $theme_url, '/' ) . '/';
		$this->manifest_path = $manifest_path;
		$this->hot_file      = $hot_file;
	}

	/**
	 * Return the origin of a valid, fresh Vite development server.
	 *
	 * @return string|null Development origin, or null when missing, stale, or invalid.
	 */
	public function get_dev_server_origin(): ?string {
		if ( ! is_file( $this->hot_file ) || ! is_readable( $this->hot_file ) ) {
			return null;
		}

		clearstatcache( true, $this->hot_file );
		$modified = filemtime( $this->hot_file );
		$age      = false === $modified ? false : time() - $modified;
		if ( false === $age || $age < 0 || $age > 15 ) {
			return null;
		}

		// phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents -- This is a local dev marker, not a remote URL.
		$origin = file_get_contents( $this->hot_file );
		if ( ! is_string( $origin ) ) {
			return null;
		}

		$origin = trim( $origin );
		if ( ! $this->is_valid_dev_server_origin( $origin ) ) {
			return null;
		}

		return rtrim( $origin, '/' );
	}

	/**
	 * Return a normalized Vite manifest entry.
	 *
	 * @param string $manifest_key Source path used as the Vite manifest key.
	 * @return array|null Entry with a relative file and zero or more CSS files.
	 */
	public function get_entry( string $manifest_key ): ?array {
		$manifest = $this->get_manifest();
		if ( ! is_array( $manifest ) || ! isset( $manifest[ $manifest_key ]['file'] ) ) {
			return null;
		}

		$file = $manifest[ $manifest_key ]['file'];
		if ( ! is_string( $file ) || ! $this->is_relative_asset_path( $file ) ) {
			return null;
		}

		$css          = isset( $manifest[ $manifest_key ]['css'] ) && is_array( $manifest[ $manifest_key ]['css'] )
			? $manifest[ $manifest_key ]['css']
			: array();
		$css          = array_values(
			array_filter(
				$css,
				function ( $path ) {
					return is_string( $path ) && $this->is_relative_asset_path( $path );
				}
			)
		);
		$dependencies = isset( $manifest[ $manifest_key ]['wordpressDependencies'] ) && is_array( $manifest[ $manifest_key ]['wordpressDependencies'] )
			? $manifest[ $manifest_key ]['wordpressDependencies']
			: array();
		$dependencies = array_values(
			array_unique(
				array_filter(
					$dependencies,
					function ( $dependency ) {
						return is_string( $dependency ) && preg_match( '/^[a-z0-9_.-]+$/i', $dependency );
					}
				)
			)
		);

		return array(
			'file'         => $file,
			'css'          => $css,
			'dependencies' => $dependencies,
		);
	}

	/**
	 * Discover runtime handles needed by a source entry during development.
	 *
	 * @param string $source_key Theme-relative source entry path.
	 * @return array WordPress script dependency handles.
	 */
	public function get_source_dependencies( string $source_key ): array {
		$source_path  = $this->theme_path . ltrim( $source_key, '/\\' );
		$dependencies = array();
		$visited      = array();
		$this->collect_source_dependencies( $source_path, $visited, $dependencies );

		$dependencies = array_values( array_unique( $dependencies ) );
		sort( $dependencies );
		return $dependencies;
	}

	/**
	 * Collect external dependencies through relative source imports.
	 *
	 * @param string $source_path Source file path.
	 * @param array  $visited     Files already inspected.
	 * @param array  $dependencies Collected WordPress handles.
	 * @return void
	 */
	private function collect_source_dependencies( string $source_path, array &$visited, array &$dependencies ): void {
		if ( isset( $visited[ $source_path ] ) || ! is_file( $source_path ) || ! is_readable( $source_path ) ) {
			return;
		}
		$visited[ $source_path ] = true;

		// phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents -- Read local theme source to determine its WordPress script dependencies.
		$source = file_get_contents( $source_path );
		if ( ! is_string( $source ) ) {
			return;
		}

		preg_match_all( '/\b(?:from\s*|import\s*(?:\(\s*)?)[\'\"]([^\'\"]+)[\'\"]/', $source, $matches );
		foreach ( $matches[1] as $module_name ) {
			$handle = $this->get_wordpress_dependency_handle( $module_name );
			if ( null !== $handle ) {
				$dependencies[] = $handle;
				continue;
			}

			if ( 0 === strpos( $module_name, '.' ) ) {
				$local_file = $this->resolve_local_source_file( dirname( $source_path ) . DIRECTORY_SEPARATOR . $module_name );
				if ( null !== $local_file ) {
					$this->collect_source_dependencies( $local_file, $visited, $dependencies );
				}
			}
		}
	}

	/**
	 * Resolve a relative import to a local JavaScript/TypeScript file.
	 *
	 * @param string $path Relative import path with its importer directory applied.
	 * @return string|null Resolved source file or null if unavailable.
	 */
	private function resolve_local_source_file( string $path ): ?string {
		$extensions = array( '.js', '.jsx', '.ts', '.tsx' );
		$candidates = pathinfo( $path, PATHINFO_EXTENSION )
			? array( $path )
			: array_merge(
				array_map(
					function ( $extension ) use ( $path ) {
						return $path . $extension;
					},
					$extensions
				),
				array_map(
					function ( $extension ) use ( $path ) {
						return $path . DIRECTORY_SEPARATOR . 'index' . $extension;
					},
					$extensions
				)
			);

		foreach ( $candidates as $candidate ) {
			if ( is_file( $candidate ) && preg_match( '/\.(?:js|jsx|ts|tsx)$/i', $candidate ) ) {
				return $candidate;
			}
		}

		return null;
	}

	/**
	 * Load and cache the manifest once per resolver instance.
	 *
	 * @return array|null Decoded manifest or null if unavailable or invalid.
	 */
	private function get_manifest(): ?array {
		if ( $this->manifest_loaded ) {
			return $this->manifest;
		}

		$this->manifest_loaded = true;
		if ( ! is_file( $this->manifest_path ) || ! is_readable( $this->manifest_path ) ) {
			return null;
		}

		$manifest = wp_json_file_decode( $this->manifest_path, array( 'associative' => true ) );
		if ( is_array( $manifest ) ) {
			$this->manifest = $manifest;
		}

		return $this->manifest;
	}

	/**
	 * Validate a plain HTTP(S) origin with no path or credentials.
	 *
	 * @param string $origin Candidate origin.
	 * @return bool Whether the origin is safe to use for development URLs.
	 */
	private function is_valid_dev_server_origin( string $origin ): bool {
		if ( false === filter_var( $origin, FILTER_VALIDATE_URL ) ) {
			return false;
		}

		$parts = wp_parse_url( $origin );
		if ( ! is_array( $parts ) || empty( $parts['scheme'] ) || empty( $parts['host'] ) ) {
			return false;
		}

		if ( ! in_array( strtolower( $parts['scheme'] ), array( 'http', 'https' ), true ) ) {
			return false;
		}

		if ( isset( $parts['user'] ) || isset( $parts['pass'] ) || isset( $parts['query'] ) || isset( $parts['fragment'] ) ) {
			return false;
		}

		return ! isset( $parts['path'] ) || '' === $parts['path'] || '/' === $parts['path'];
	}

	/**
	 * Ensure a manifest asset path is relative and cannot escape the build directory.
	 *
	 * @param string $path Candidate manifest path.
	 * @return bool Whether the relative path is safe.
	 */
	private function is_relative_asset_path( string $path ): bool {
		$normalized = str_replace( '\\', '/', rawurldecode( $path ) );
		if (
			'' === $normalized ||
			false !== strpos( $normalized, "\0" ) ||
			'/' === $normalized[0] ||
			false !== filter_var( $normalized, FILTER_VALIDATE_URL )
		) {
			return false;
		}

		return ! in_array( '..', explode( '/', $normalized ), true );
	}

	/**
	 * Map a module external to the corresponding WordPress registered script.
	 *
	 * @param string $module_name Imported external module.
	 * @return string|null WordPress script handle, or null when not a supported external.
	 */
	private function get_wordpress_dependency_handle( string $module_name ): ?string {
		if ( preg_match( '/^@wordpress\/([a-z0-9-]+)$/', $module_name, $matches ) ) {
			return 'wp-' . $matches[1];
		}

		if ( in_array( $module_name, array( 'react', 'react-dom', 'react/jsx-runtime' ), true ) ) {
			return 'wp-element';
		}

		if ( in_array( $module_name, array( 'jquery', 'lodash' ), true ) ) {
			return $module_name;
		}

		return null;
	}

	/**
	 * Get the theme filesystem root.
	 *
	 * @return string
	 */
	public function get_theme_path(): string {
		return $this->theme_path;
	}

	/**
	 * Get the theme public URL.
	 *
	 * @return string
	 */
	public function get_theme_url(): string {
		return $this->theme_url;
	}
}
